    if (scenario === 'midday') {
      staticData[stageKey] = 'gmail';
      return routeTool('calendar', 'get', { ...afternoonWindow(), maxResults: 10 });
    }
    if (scenario === 'evening') {
      staticData[stageKey] = 'daily';
      return routeTool('calendar', 'get', { ...tomorrowWindow(), maxResults: 10 });
    }
    if (scenario === 'weekly_review') {
      staticData[stageKey] = 'gmail';
      return routeTool('calendar', 'get', { ...weekToNowWindow(), maxResults: 15 });
    }
    if (scenario === 'premeet') {
      staticData[stageKey] = 'final';
      return routeTool('calendar', 'get', { ...nextHourWindow(), maxResults: 3, scenario: 'premeet' });
    }
  }
  if (stage === 'gmail' && (scenario === 'morning' || scenario === 'midday' || scenario === 'weekly_review')) {
    const results = staticData['opsAgentToolResults_' + execId] || {};
    if (scenario !== 'weekly_review' && scenario !== 'premeet' && calendarStartsWithin(results.calendar || '', 5)) {
      staticData.lastOpsAgentSkip = { at: new Date().toISOString(), reason: 'meeting_starting', scenario };
      delete staticData[stageKey];
      return directFinal('skip');
    }
    staticData[stageKey] = 'final';
    const query = scenario === 'morning' ? 'newer_than:1d' : scenario === 'weekly_review' ? 'newer_than:7d' : 'newer_than:6h';
    return routeTool('gmail', 'search', { query, maxResults: scenario === 'weekly_review' ? 5 : 3 });
  }
  const storedOpsAgentFinalKey = 'opsAgentFinal_' + execId;
  if (stage === 'daily' && scenario === 'evening') {
    const opsAgentFinal = buildOpsAgentFinal(scenario);
    staticData[storedOpsAgentFinalKey] = opsAgentFinal;
    staticData[stageKey] = 'final';
    return routeTool('memory', 'write', { target: 'daily', memoryContent: buildEveningDailyMemory(opsAgentFinal), scenario });
  }
  if (stage === 'final') {
    const opsAgentFinal = staticData[storedOpsAgentFinalKey] || buildOpsAgentFinal(scenario);
    delete staticData[storedOpsAgentFinalKey];
    if (scenario !== 'premeet') recordOpsAgentRun(scenario, opsAgentFinal, 'heartbeat');
    delete staticData[stageKey];
    return directFinal(opsAgentFinal);
  }
}

const params = parseParams(paramsMatch && paramsMatch[1]);
if (params.__parseError) {
  return directFinal('Ich konnte die Tool Parameter nicht lesen. Bitte formuliere die Anfrage nochmal klarer.', { toolError: params.__parseError });
}
if (actionMatch) {
  const tool = actionMatch[1].toLowerCase();
  let toolWorkflow = 'none';
  let operation = '';
  if (tool === 'calendar') {
    toolWorkflow = 'calendar';
    operation = params.operation || 'get';
  } else if (tool === 'gmail') {
    toolWorkflow = 'gmail';
    operation = params.operation || 'search';
  } else if (tool === 'memory') {
    toolWorkflow = 'memory';
    operation = params.operation || 'write';
  } else if (tool.startsWith('gmail_')) {
    toolWorkflow = 'gmail';
    operation = tool.replace('gmail_', '');
  } else if (tool.startsWith('calendar_')) {
    toolWorkflow = 'calendar';
    operation = tool.replace('calendar_', '');
  } else if (tool.startsWith('notion_')) {
    toolWorkflow = 'notion';
    operation = tool.replace('notion_', '');
  } else if (tool.startsWith('memory_')) {
    toolWorkflow = 'memory';
    operation = tool.replace('memory_', '');
  } else {
    return directFinal('Dieses Tool kenne ich nicht ' + tool + '. Ich habe die Anfrage nicht ausgefuehrt.', { toolError: 'unknown_tool', attemptedTool: tool });
  }
  const allowed = {
    gmail: ['search', 'read', 'draft'],
    calendar: ['get', 'create'],
    notion: ['search', 'read', 'create', 'update'],
    memory: ['write']
  };
  if (!allowed[toolWorkflow].includes(operation)) {
    return directFinal('Diese Tool Operation ist nicht erlaubt ' + tool + '.', { toolError: 'invalid_operation', attemptedTool: tool });
  }
  if (toolWorkflow === 'gmail' && operation === 'read' && !params.messageId) {
    return directFinal('Welche E-Mail soll ich lesen? Mir fehlt die messageId.', { toolError: 'missing_messageId', attemptedTool: tool });
  }
  if (toolWorkflow === 'gmail' && operation === 'draft' && (!params.to || !params.subject || !params.body)) {
    return directFinal('Für den E-Mail-Entwurf fehlen Empfänger, Betreff oder Inhalt.', { toolError: 'missing_gmail_draft_params', attemptedTool: tool });
  }
  if (toolWorkflow === 'calendar' && operation === 'create' && (!params.title || !params.start || !params.end)) {
    return directFinal('Für den Termin fehlen Titel, Start oder Ende.', { toolError: 'missing_calendar_create_params', attemptedTool: tool });
  }
  if (toolWorkflow === 'notion' && ['read', 'update'].includes(operation) && !params.pageId) {
    return directFinal('Für diese Notion-Aktion fehlt die pageId. Ich muss zuerst suchen oder du gibst mir die ID.', { toolError: 'missing_pageId', attemptedTool: tool });
  }
  if (toolWorkflow === 'memory' && operation === 'write' && !(params.content || params.body)) {
    return directFinal('Was soll ich speichern? Mir fehlt der content für memory_write.', { toolError: 'missing_memory_content', attemptedTool: tool });
  }
  const calendarTarget = String(params.calendar || params.targetCalendar || 'primary-project').toLowerCase();
  const normalizedCalendar = ['privat', 'private', 'personal', 'gmail', 'googlemail', 'personal'].some((value) => calendarTarget.includes(value)) ? 'privat' : 'primary-project';
  const output = {
    needsTool: true,
    toolWorkflow,
    operation,
    query: params.query || '',
    messageId: params.messageId || '',
    to: params.to || '',
    subject: params.subject || '',
    body: params.body || '',
    title: params.title || '',
    description: params.description || '',
    start: params.start || '',
    end: params.end || '',
    calendar: normalizedCalendar,
    timeMin: params.timeMin || '',
    timeMax: params.timeMax || '',
    maxResults: parseInt(params.maxResults, 10) || 10,
    pageId: params.pageId || '',
    name: params.name || '',
    company: params.company || '',
    email: params.email || '',
    status: params.status || 'Lead',
    dealValue: parseInt(params.dealValue, 10) || 0,
    branche: params.branche || '',
    budget: params.budget || '',
    notes: params.notes || '',
    target: params.target || 'memory',
    memoryContent: params.content || params.body || '',
    originalResponse: response,
    attemptedTool: tool,
    ...contextFields
  };
  if (debugEnabled) {
    staticData.lastAgentAction = { at: new Date().toISOString(), tool, toolWorkflow, operation, params };
  }
  return [ { json: output } ];
}

delete staticData['loopCount_' + execId];
const finalAnswer = finalMatch ? finalMatch[1].trim() : response;
const lastAction = staticData.lastAgentAction || {};
return [ { json: { needsTool: false, toolWorkflow: 'none', finalAnswer, ...contextFields, debugLastAction: lastAction } } ];

function polishVisibleText(text) {
  let output = String(text || '').replace(/^FINAL:\s*/i, '').trim();
  const replacements = [
    [/Management meint/gi, 'OpsAgent sagt'],
    [/Management[- ]Reset/gi, 'Reset'],
    [/Lagebild/gi, 'Stand'],
    [/\bCoach\b/gi, 'OpsAgent'],
    [/\bHebel\b/gi, 'Ansatz'],
    [/Gamechanger/gi, 'Wendepunkt'],
    [/Qwen/gi, 'Modell'],
    [/naechsten/gi, 'nächsten'],
    [/naechste/gi, 'nächste'],
    [/naechster/gi, 'nächster'],
    [/laeuft/gi, 'läuft'],
    [/fuer/gi, 'für'],
    [/ueber/gi, 'über'],
    [/zurueck/gi, 'zurück'],
    [/spaeter/gi, 'später'],
    [/pruef/gi, 'prüf'],
    [/waehlen/gi, 'wählen'],
    [/groesste/gi, 'größte'],
    [/haengt/gi, 'hängt'],
    [/loesen/gi, 'lösen'],
    [/schliessen/gi, 'schließen'],
    [/oeffnen/gi, 'öffnen']
  ];
  for (const [pattern, value] of replacements) output = output.replace(pattern, value);
  output = output.replace(new RegExp('\\\\([_*\\[\\]()~`>#+\\-=|{}.!])', 'g'), '$1');
  output = output.replace(/\*\*(.*?)\*\*/g, '$1');
  output = output.replace(/__(.*?)__/g, '$1');
  output = output.replace(/\*(.*?)\*/g, '$1');
  output = output.replace(/`([^`]*)`/g, '$1');
  output = output.replace(/:/g, '.');
  output = output.replace(/\s+([.,!?])/g, '$1');
  output = output.replace(/&/g, '&amp;');
  output = output.replace(/</g, '&lt;');
  output = output.replace(/>/g, '&gt;');
  output = output.replace(/\n{3,}/g, '\n\n');
  return output.trim().slice(0, 3800);
}
